const INLINE_CSS = "/* dashboard.css */\n/* dashboard.css — tokens, background, grid, top bar.\n   Every colour goes through a CSS variable — none are hard-coded below. */\n\n/* The panel scrolls itself only where its parent gives it a height (the\n   standalone page). Home Assistant does not, so there the panel has nothing to\n   scroll and a swipe has to chain on to the document — which is why there is no\n   overscroll-behavior: contain here. With it, one finger could not scroll the\n   page on a phone. */\n:host {\n  display: block;\n  width: 100%;\n  height: 100%;\n  overflow: auto;\n\n  /* ─── surfaces ─── */\n  --bg-0: #06090f;\n  --bg-1: #0a1017;\n  --bg-2: #0e1622;\n  --surface: rgba(255, 255, 255, .038);\n  --surface-2: rgba(255, 255, 255, .065);\n  --surface-3: rgba(255, 255, 255, .1);\n  --border: rgba(255, 255, 255, .075);\n  --border-strong: rgba(255, 255, 255, .16);\n\n  /* ─── text ─── */\n  --text-0: #e9eff8;\n  --text-1: #96a2b5;\n  --text-2: #5d6a7d;\n\n  /* ─── semantic colours ─── */\n  --solar-color: #ffb020;\n  --battery-color: #2edd8b;\n  --grid-color: #4d9bff;\n  --load-color: #dfe7f4;\n  --inverter-color: #a98bff;\n  --phase-color: #34d3e2;\n  --generator-color: #ff7a59;\n  --accent-color: #ffb020;\n  --ok-color: #2edd8b;\n  --warn-color: #ffa62e;\n  --danger-color: #ff5c5c;\n  --offline-color: #6b7686;\n\n  /* ─── geometry ─── */\n  --radius: 20px;\n  --radius-sm: 13px;\n  --radius-xs: 9px;\n  --gap: 14px;\n  --pad: 18px;\n  --shadow-card: 0 20px 44px -26px rgba(0, 0, 0, .9);\n  --inner-light: inset 0 1px 0 rgba(255, 255, 255, .055);\n  --font: \"Inter\", \"SF Pro Display\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", system-ui, sans-serif;\n\n  color: var(--text-0);\n  font-family: var(--font);\n  font-size: 14px;\n  line-height: 1.35;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n  font-variant-numeric: tabular-nums;\n  background:\n    radial-gradient(1100px 620px at 12% -8%, rgba(255, 176, 32, .085), transparent 62%),\n    radial-gradient(980px 560px at 92% 4%, rgba(77, 155, 255, .075), transparent 60%),\n    radial-gradient(900px 700px at 50% 108%, rgba(46, 221, 139, .05), transparent 62%),\n    linear-gradient(180deg, var(--bg-1) 0%, var(--bg-0) 60%, #04070c 100%);\n  background-attachment: fixed;\n}\n\n*, *::before, *::after { box-sizing: border-box; }\n\n.app {\n  min-height: 100%;\n  padding: 12px clamp(10px, 1.4vw, 22px) 26px;\n  max-width: 2400px;\n  margin: 0 auto;\n  display: flex;\n  flex-direction: column;\n  gap: var(--gap);\n}\n\n/* ─────────────────────────── top bar ─────────────────────────── */\n\n.topbar {\n  position: sticky;\n  top: 0;\n  z-index: 20;\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 8px 12px;\n  border-radius: var(--radius-sm);\n  background: linear-gradient(180deg, rgba(14, 22, 34, .82), rgba(10, 16, 23, .72));\n  border: 1px solid var(--border);\n  box-shadow: var(--inner-light), 0 10px 30px -22px rgba(0, 0, 0, .9);\n  backdrop-filter: blur(16px) saturate(140%);\n  -webkit-backdrop-filter: blur(16px) saturate(140%);\n}\n\n.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }\n\n.brand-mark {\n  display: grid;\n  place-items: center;\n  width: 34px; height: 34px;\n  border-radius: 11px;\n  color: #1a1206;\n  background: linear-gradient(150deg, #ffd166, var(--solar-color));\n  box-shadow: 0 6px 18px -8px rgba(255, 176, 32, .8);\n  flex: none;\n}\n\n.brand-title {\n  display: flex; align-items: center; gap: 8px;\n  font-size: 15px; font-weight: 650; letter-spacing: .1em;\n}\n.topbar-spacer { flex: 1 1 auto; }\n\n/* The period selector in the top bar. It governs the whole page, so it is the\n   first control after the brand — and it must not push the clock, the\n   connection state and the two icon buttons off a phone screen. */\n.topbar-nav { display: flex; align-items: center; min-width: 0; }\n/* Only a custom interval is allowed to push the bar onto a second line. */\n.topbar { flex-wrap: wrap; row-gap: 8px; }\n.topbar .date-nav { gap: 8px; flex-wrap: nowrap; }\n.topbar .nav-period { flex: none; }\n.topbar .nav-label { min-width: 118px; padding: 4px 9px; }\n/* The form controls default to width:100%, which inside a flex row means \"take\n   the whole line\". Here the period list is one chip among several. */\n.topbar .nav-range-select { flex: none; width: auto; padding: 4px 24px 4px 8px; font-size: 11.5px; }\n.topbar .nav-custom { flex: none; }\n.topbar .nav-range-input { width: 124px; }\n\n.badge {\n  font-size: 9.5px; font-weight: 700; letter-spacing: .12em;\n  padding: 2px 6px; border-radius: 5px;\n  border: 1px solid var(--border-strong);\n  color: var(--text-1);\n}\n.badge-demo { color: var(--warn-color); border-color: rgba(255, 166, 46, .45); background: rgba(255, 166, 46, .1); }\n.badge[hidden] { display: none; }\n\n.icon-btn {\n  display: grid; place-items: center;\n  width: 34px; height: 34px; flex: none;\n  border-radius: 10px;\n  border: 1px solid var(--border);\n  background: var(--surface);\n  color: var(--text-1);\n  cursor: pointer;\n  transition: color .15s, background .15s, border-color .15s, transform .12s;\n}\n.icon-btn:hover { color: var(--text-0); background: var(--surface-2); border-color: var(--border-strong); }\n.icon-btn:active { transform: scale(.94); }\n.icon-btn:focus-visible, button:focus-visible, select:focus-visible, input:focus-visible {\n  outline: 2px solid color-mix(in srgb, var(--accent-color) 70%, transparent);\n  outline-offset: 2px;\n}\n\n.lang-btn {\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: .06em;\n  font-family: var(--font);\n}\n\n.last-update { display: flex; flex-direction: column; align-items: flex-end; line-height: 1.25; }\n.lu-label { font-size: 9.5px; letter-spacing: .13em; text-transform: uppercase; color: var(--text-2); }\n.lu-line { display: flex; align-items: baseline; gap: 6px; }\n.lu-value { font-size: 14px; font-weight: 550; color: var(--text-0); }\n.lu-ago { font-size: 10.5px; color: var(--text-2); }\n\n.status-chip {\n  display: flex; align-items: center; gap: 7px;\n  padding: 6px 11px;\n  border-radius: 999px;\n  border: 1px solid var(--border);\n  background: var(--surface);\n  font-size: 11px; font-weight: 600; letter-spacing: .1em;\n  color: var(--text-1);\n  white-space: nowrap;\n}\n.status-chip .dot {\n  width: 7px; height: 7px; border-radius: 50%;\n  background: var(--offline-color);\n  box-shadow: 0 0 0 0 currentColor;\n}\n.status-chip[data-state=\"ok\"] { color: var(--ok-color); border-color: rgba(46, 221, 139, .3); background: rgba(46, 221, 139, .08); }\n.status-chip[data-state=\"ok\"] .dot { background: var(--ok-color); animation: pulse-dot 2.6s ease-in-out infinite; }\n.status-chip[data-state=\"warn\"] { color: var(--warn-color); border-color: rgba(255, 166, 46, .34); background: rgba(255, 166, 46, .09); }\n.status-chip[data-state=\"warn\"] .dot { background: var(--warn-color); animation: pulse-dot 1.1s ease-in-out infinite; }\n.status-chip[data-state=\"bad\"] { color: var(--danger-color); border-color: rgba(255, 92, 92, .34); background: rgba(255, 92, 92, .09); }\n.status-chip[data-state=\"bad\"] .dot { background: var(--danger-color); }\n\n@keyframes pulse-dot {\n  0%, 100% { box-shadow: 0 0 0 0 rgba(255, 255, 255, 0); }\n  50% { box-shadow: 0 0 0 5px rgba(255, 255, 255, .05); }\n}\n\n/* ────────────────── historical mode banner ────────────────── */\n\n.above-grid { display: flex; flex-direction: column; gap: 8px; }\n\n.history-bar {\n  display: flex; align-items: center; gap: 11px;\n  padding: 9px 14px;\n  border-radius: var(--radius-xs);\n  border: 1px solid color-mix(in srgb, var(--accent-color) 34%, transparent);\n  background: color-mix(in srgb, var(--accent-color) 9%, transparent);\n  color: var(--text-0);\n}\n\n/* A period that still contains the present is not a warning, only a statement\n   of what the tiles add up: quieter than the historical banner. */\n.history-bar[data-state=\"partial\"] {\n  border-color: var(--border);\n  background: var(--surface);\n}\n.history-bar[hidden] { display: none; }\n.history-icon { display: grid; place-items: center; color: var(--accent-color); flex: none; }\n.history-label { font-size: 12px; font-weight: 700; letter-spacing: .12em; }\n.history-hint { flex: 1 1 auto; font-size: 11.5px; color: var(--text-2); }\n.history-now { padding: 5px 12px; }\n\n/* ─────────────────────────── notices ─────────────────────────── */\n\n.notices { display: flex; flex-direction: column; gap: 8px; }\n.notices:empty { display: none; }\n.notice {\n  display: flex; align-items: center; gap: 10px;\n  padding: 9px 13px;\n  border-radius: var(--radius-xs);\n  border: 1px solid var(--border);\n  background: var(--surface);\n  font-size: 12.5px; color: var(--text-1);\n}\n.notice-icon { display: grid; place-items: center; color: var(--text-2); flex: none; }\n.notice-text { flex: 1 1 auto; }\n.notice-text b { color: var(--text-0); font-weight: 600; }\n.notice-text code { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px; color: var(--accent-color); }\n.notice-warn { border-color: rgba(255, 166, 46, .28); background: rgba(255, 166, 46, .07); color: #f2d3a2; }\n.notice-warn .notice-icon { color: var(--warn-color); }\n.notice-action {\n  flex: none;\n  padding: 5px 10px; border-radius: 8px;\n  border: 1px solid var(--border-strong);\n  background: var(--surface-2);\n  color: var(--text-0);\n  font: inherit; font-size: 11.5px; font-weight: 600;\n  cursor: pointer;\n}\n.notice-action:hover { background: var(--surface-3); }\n\n/* ─────────────────────────── layout grid ─────────────────────────── */\n\n.grid {\n  display: grid;\n  grid-template-columns: repeat(12, minmax(0, 1fr));\n  gap: var(--gap);\n}\n\n/* The flow diagram spans two rows, with battery and grid on the right.\n   The bottom row is a self-fitting grid, so hidden cards leave no holes. */\n.card-flow { grid-column: 1 / span 7; grid-row: 1 / span 2; }\n.card-battery { grid-column: 8 / span 5; grid-row: 1; }\n.card-grid { grid-column: 8 / span 5; grid-row: 2; }\n.kpi-row { grid-column: 1 / span 12; grid-row: 3; }\n.card-chart { grid-column: 1 / span 12; grid-row: 4; }\n.detail-row { grid-column: 1 / span 12; grid-row: 5; }\n\n.kpi-row, .detail-row {\n  display: grid;\n  gap: var(--gap);\n}\n.kpi-row { grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); }\n.detail-row { grid-template-columns: repeat(auto-fit, minmax(258px, 1fr)); }\n\n/* A period strictly in the past has no instantaneous values, so everything\n   built from them is hidden rather than shown empty — including the battery and\n   grid cards, which would otherwise print live readings under a banner saying\n   live values are unavailable. */\n.app[data-mode=\"history\"] .card-flow,\n.app[data-mode=\"history\"] .card-battery,\n.app[data-mode=\"history\"] .card-grid,\n.app[data-mode=\"history\"] .detail-row { display: none; }\n\n/* With the live cards gone the chart owns the page instead of leaving a hole. */\n.app[data-mode=\"history\"] .kpi-row { grid-row: 1; }\n.app[data-mode=\"history\"] .card-chart { grid-row: 2; }\n\n/* ─────────────────────────── cards ─────────────────────────── */\n\n.card {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  padding: var(--pad);\n  border-radius: var(--radius);\n  border: 1px solid var(--border);\n  background: linear-gradient(168deg, rgba(255, 255, 255, .045), rgba(255, 255, 255, .012) 55%, rgba(255, 255, 255, .022));\n  box-shadow: var(--inner-light), var(--shadow-card);\n  backdrop-filter: blur(14px) saturate(130%);\n  -webkit-backdrop-filter: blur(14px) saturate(130%);\n  min-width: 0;\n}\n.card[hidden] { display: none; }\n\n.card-head {\n  display: flex; align-items: center; justify-content: space-between;\n  gap: 10px; margin-bottom: 14px;\n}\n.card-title { display: flex; align-items: center; gap: 8px; min-width: 0; }\n.card-icon { display: grid; place-items: center; color: var(--tone, var(--text-2)); }\n.card-title-text {\n  font-size: 11px; font-weight: 650; letter-spacing: .15em;\n  text-transform: uppercase; color: var(--text-1);\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n}\n.card-actions { display: flex; align-items: center; gap: 10px; }\n\n.tone-solar { --tone: var(--solar-color); }\n.tone-battery { --tone: var(--battery-color); }\n.tone-grid { --tone: var(--grid-color); }\n.tone-load { --tone: var(--load-color); }\n.tone-house { --tone: var(--load-color); }\n.tone-inverter { --tone: var(--inverter-color); }\n.tone-phase { --tone: var(--phase-color); }\n.tone-generator { --tone: var(--generator-color); }\n.tone-accent { --tone: var(--accent-color); }\n\n.section-label {\n  font-size: 10px; font-weight: 650; letter-spacing: .14em;\n  text-transform: uppercase; color: var(--text-2);\n}\n.hint {\n  font-size: 9.5px; letter-spacing: .1em; text-transform: uppercase;\n  color: var(--text-2); border: 1px dashed var(--border-strong);\n  padding: 1px 6px; border-radius: 6px; cursor: help;\n}\n\n/* big numbers */\n.big-value { display: flex; align-items: baseline; gap: 6px; }\n.big-num { font-size: clamp(30px, 3vw, 44px); font-weight: 300; letter-spacing: -.02em; line-height: 1; }\n.big-unit { font-size: 14px; font-weight: 500; color: var(--text-1); }\n\n.card-hero { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; }\n\n.dir-badge {\n  font-size: 9.5px; font-weight: 700; letter-spacing: .1em;\n  padding: 4px 8px; border-radius: 7px;\n  border: 1px solid var(--border);\n  background: var(--surface);\n  color: var(--text-2);\n  white-space: nowrap;\n}\n.dir-badge[data-dir=\"import\"] { color: var(--grid-color); border-color: color-mix(in srgb, var(--grid-color) 34%, transparent); background: color-mix(in srgb, var(--grid-color) 10%, transparent); }\n.dir-badge[data-dir=\"export\"] { color: var(--battery-color); border-color: color-mix(in srgb, var(--battery-color) 34%, transparent); background: color-mix(in srgb, var(--battery-color) 10%, transparent); }\n.dir-badge[data-state=\"online\"] { color: var(--ok-color); border-color: color-mix(in srgb, var(--ok-color) 34%, transparent); background: color-mix(in srgb, var(--ok-color) 10%, transparent); }\n.dir-badge[data-state=\"fault\"] { color: var(--danger-color); border-color: color-mix(in srgb, var(--danger-color) 40%, transparent); background: color-mix(in srgb, var(--danger-color) 12%, transparent); }\n.dir-badge[data-state=\"offline\"], .dir-badge[data-state=\"stale\"] { color: var(--offline-color); }\n.dir-badge[data-state=\"standby\"] { color: var(--warn-color); border-color: color-mix(in srgb, var(--warn-color) 34%, transparent); }\n\n/* Stat rows take the remaining card height and spread evenly, so cards in the\n   same row look complete instead of empty at the bottom. */\n.stat-rows { display: flex; flex-direction: column; flex: 1 1 auto; justify-content: space-evenly; min-height: 0; }\n.stat-rows > .stat-row { flex: 0 0 auto; }\n.stat-row {\n  display: flex; align-items: baseline; justify-content: space-between;\n  gap: 10px; padding: 7px 0;\n  border-top: 1px solid var(--border);\n  font-size: 12.5px;\n}\n.stat-row:first-child { border-top: none; }\n.stat-row[hidden] { display: none; }\n.stat-label { color: var(--text-2); }\n.stat-value { color: var(--text-0); font-weight: 550; white-space: nowrap; }\n\n/* Values that can be drilled into. Only roles with a mapped entity get the\n   affordance — setInteractiveRoles() adds the class. */\n[data-role].is-clickable { cursor: pointer; }\n.stat-row.is-clickable:hover, .string-row.is-clickable:hover, .phase-row.is-clickable:hover {\n  background: var(--surface);\n  box-shadow: inset 0 0 0 1px var(--border);\n  border-radius: 8px;\n}\n.kpi.is-clickable:hover { border-color: var(--border-strong); background: var(--surface-2); }\n.flow-node.is-clickable:hover .node-body { border-color: color-mix(in srgb, var(--tone) 55%, transparent); }\n[data-role].is-clickable:focus-visible {\n  outline: 2px solid color-mix(in srgb, var(--accent-color) 70%, transparent);\n  outline-offset: 2px;\n  border-radius: 8px;\n}\n\n/* bars */\n.bar {\n  display: block; height: 5px; border-radius: 3px;\n  background: rgba(255, 255, 255, .06);\n  overflow: hidden;\n}\n.bar-fill {\n  display: block; height: 100%; width: var(--w, 0%);\n  border-radius: 3px;\n  background: linear-gradient(90deg, color-mix(in srgb, var(--tone) 55%, transparent), var(--tone));\n  transition: width .5s cubic-bezier(.22, .61, .36, 1);\n}\n\n.spinner {\n  width: 13px; height: 13px; flex: none;\n  border-radius: 50%;\n  border: 1.6px solid var(--border-strong);\n  border-top-color: var(--accent-color);\n  animation: spin .8s linear infinite;\n}\n.spinner[hidden] { display: none; }\n@keyframes spin { to { transform: rotate(360deg); } }\n\n/* scrollbar */\n:host::-webkit-scrollbar { width: 10px; height: 10px; }\n:host::-webkit-scrollbar-track { background: transparent; }\n:host::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, .1); border-radius: 5px; border: 2px solid transparent; background-clip: content-box; }\n:host::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, .2); background-clip: content-box; }\n\n/* Animation control. 'auto' follows the system preference, 'on' overrides it\n   deliberately, 'off' disables animation regardless. */\n@media (prefers-reduced-motion: reduce) {\n  .deye-root:not([data-anim=\"on\"]) *,\n  .deye-root:not([data-anim=\"on\"]) *::before,\n  .deye-root:not([data-anim=\"on\"]) *::after {\n    animation-duration: .001ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: .001ms !important;\n  }\n}\n.deye-root[data-anim=\"off\"] *,\n.deye-root[data-anim=\"off\"] *::before,\n.deye-root[data-anim=\"off\"] *::after {\n  animation-duration: .001ms !important;\n  animation-iteration-count: 1 !important;\n  transition-duration: .001ms !important;\n}\n\n/* components.css */\n/* components.css — flow diagram, battery, KPI, charts, detail cards. */\n\n/* ═══════════════════════════ ENERGY FLOW ═══════════════════════════ */\n\n.card-flow { padding: var(--pad) var(--pad) 14px; }\n\n.flow-stage {\n  position: relative;\n  width: min(100%, calc(var(--flow-max-h, 62vh) * var(--flow-ratio, 1.4286)));\n  aspect-ratio: var(--flow-aspect, 1000 / 700);\n  margin: 0 auto;\n  --bead-dash: 1.3 17;\n  --bead-period: 18.3;\n}\n.flow-stage[data-layout=\"narrow\"] { --bead-dash: 1.1 13; --bead-period: 14.1; }\n\n.flow-svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }\n\n.flow-link { --link-color: var(--text-2); }\n.link-solar { --link-color: var(--solar-color); }\n.link-battery { --link-color: var(--battery-color); }\n.link-grid { --link-color: var(--grid-color); }\n.link-load { --link-color: var(--load-color); }\n.link-generator { --link-color: var(--generator-color); }\n/* The UA stylesheet's [hidden] rule does not apply to SVG, so a link that the\n   current layout does not use would stay in the render and accessibility trees\n   with empty paths. */\n.flow-link[hidden] { display: none; }\n\n.link-track { stroke: rgba(255, 255, 255, .06); stroke-width: 9; stroke-linecap: round; }\n.flow-stage[data-layout=\"narrow\"] .link-track { stroke-width: 7; }\n\n.link-glow {\n  stroke: var(--link-color);\n  stroke-width: 9; stroke-linecap: round;\n  opacity: calc(.05 + .2 * var(--intensity, 0));\n  transition: opacity .6s ease;\n}\n.flow-stage[data-layout=\"narrow\"] .link-glow { stroke-width: 7; }\n\n.link-beads {\n  stroke: var(--link-color);\n  stroke-width: 4.6; stroke-linecap: round;\n  stroke-dasharray: var(--bead-dash);\n  opacity: 0;\n  transition: opacity .5s ease;\n}\n.flow-stage[data-layout=\"narrow\"] .link-beads { stroke-width: 4; }\n\n.flow-link[data-dir=\"toHub\"] .link-beads,\n.flow-link[data-dir=\"fromHub\"] .link-beads {\n  opacity: calc(.45 + .55 * var(--intensity, 0));\n  animation: bead-run var(--dur, 1.4s) linear infinite;\n}\n.flow-link[data-dir=\"fromHub\"] .link-beads { animation-direction: reverse; }\n@keyframes bead-run { to { stroke-dashoffset: calc(-1 * var(--bead-period)); } }\n\n/* ─── nodes ─── */\n\n.flow-nodes, .flow-labels { position: absolute; inset: 0; pointer-events: none; }\n\n.flow-node {\n  position: absolute;\n  width: var(--node-size, 15%);\n  aspect-ratio: 1;\n  transform: translate(-50%, -50%);\n  pointer-events: auto;\n}\n\n.node-glow {\n  position: absolute; inset: -18%;\n  border-radius: 50%;\n  background: radial-gradient(circle at 50% 50%, color-mix(in srgb, var(--tone) 22%, transparent), transparent 68%);\n  opacity: .55;\n}\n\n.node-body {\n  position: relative;\n  width: 100%; height: 100%;\n  border-radius: 50%;\n  border: 1px solid color-mix(in srgb, var(--tone) 24%, var(--border));\n  background:\n    radial-gradient(130% 110% at 50% -10%, color-mix(in srgb, var(--tone) 15%, transparent), transparent 60%),\n    linear-gradient(180deg, rgba(255, 255, 255, .055), rgba(255, 255, 255, .012));\n  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .08), 0 18px 36px -22px rgba(0, 0, 0, .95);\n  backdrop-filter: blur(10px);\n  -webkit-backdrop-filter: blur(10px);\n  display: flex; flex-direction: column;\n  align-items: center; justify-content: center;\n  gap: 1px;\n  container-type: inline-size;\n  overflow: hidden;\n}\n\n.node-icon { color: var(--tone); display: grid; place-items: center; opacity: .95; }\n.node-icon .icn { width: 20px; height: 20px; width: 15cqw; height: 15cqw; }\n.node-label {\n  font-size: 11px;\n  font-size: 8.2cqw; font-weight: 650; letter-spacing: .13em;\n  color: var(--text-2); text-transform: uppercase;\n}\n.node-value { display: flex; align-items: baseline; gap: .25em; margin-top: .5cqw; }\n.node-num { font-size: 27px; font-size: 21cqw; font-weight: 300; line-height: 1; letter-spacing: -.02em; color: var(--text-0); }\n.node-unit { font-size: 12px; font-size: 8.6cqw; font-weight: 500; color: var(--text-1); }\n.node-sub { font-size: 10px; font-size: 7.6cqw; color: var(--text-2); text-align: center; padding: 0 6%; }\n/* On a narrow screen this text would be 6-7 px. The values are already in the\n   link labels and the KPI cards, so hide it here. */\n.flow-stage[data-layout=\"narrow\"] .node-sub { display: none; }\n.flow-stage[data-layout=\"narrow\"] .node-num { font-size: 22px; font-size: 23cqw; }\n.flow-stage[data-layout=\"narrow\"] .node-label { font-size: 10px; font-size: 10.5cqw; color: var(--text-1); }\n.flow-stage[data-layout=\"narrow\"] .node-icon .icn { width: 16px; height: 16px; width: 17cqw; height: 17cqw; }\n\n.node-level {\n  display: block; width: 46%; height: 6px; height: 4.5cqw; max-height: 7px;\n  margin-top: .8cqw;\n  border-radius: 99px;\n  background: rgba(255, 255, 255, .09);\n  overflow: hidden;\n}\n.node-level-fill {\n  display: block; height: 100%; width: var(--level, 0%);\n  border-radius: 99px;\n  background: linear-gradient(90deg, color-mix(in srgb, var(--tone) 60%, transparent), var(--tone));\n  transition: width .6s cubic-bezier(.22, .61, .36, 1);\n}\n\n.node-generator { --tone: var(--generator-color); }\n.node-battery[data-band=\"mid\"] { --tone: #ffd166; }\n.node-battery[data-band=\"low\"] { --tone: var(--warn-color); }\n.node-battery[data-band=\"critical\"] { --tone: var(--danger-color); }\n.node-battery[data-band=\"unknown\"] { --tone: var(--offline-color); }\n\n/* ─── central node (inverter) ─── */\n\n.node-inverter { width: var(--hub-size, 19%); --tone: var(--inverter-color); }\n\n.inv-ring {\n  position: absolute; inset: -9%;\n  border-radius: 50%;\n  padding: 1.4px;\n  background: conic-gradient(from 0deg, transparent 0 54%, color-mix(in srgb, var(--tone) 85%, transparent) 74%, transparent 86%);\n  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);\n  -webkit-mask-composite: xor;\n  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);\n  mask-composite: exclude;\n  animation: ring-spin 7.5s linear infinite;\n  opacity: .9;\n}\n@keyframes ring-spin { to { transform: rotate(360deg); } }\n\n.inv-body {\n  position: relative;\n  width: 100%; height: 100%;\n  border-radius: 27%;\n  border: 1px solid color-mix(in srgb, var(--tone) 30%, var(--border));\n  background:\n    radial-gradient(120% 110% at 50% -10%, color-mix(in srgb, var(--tone) 18%, transparent), transparent 58%),\n    linear-gradient(180deg, rgba(255, 255, 255, .07), rgba(255, 255, 255, .02));\n  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .1), 0 24px 48px -26px rgba(0, 0, 0, 1);\n  backdrop-filter: blur(12px);\n  -webkit-backdrop-filter: blur(12px);\n  display: flex; flex-direction: column; align-items: center; justify-content: center;\n  gap: 1.5cqw;\n  container-type: inline-size;\n}\n.inv-name { font-size: 12px; font-size: 9.5cqw; font-weight: 700; letter-spacing: .2em; color: var(--text-1); }\n.inv-power { display: flex; align-items: baseline; gap: .22em; }\n.inv-power-num { font-size: 40px; font-size: 24cqw; font-weight: 300; line-height: 1; letter-spacing: -.025em; }\n.inv-power-unit { font-size: 13px; font-size: 9cqw; font-weight: 500; color: var(--text-1); }\n.inv-rated { font-size: 10px; font-size: 7.4cqw; color: var(--text-2); }\n.inv-rated:empty { display: none; }\n.inv-status { display: flex; align-items: center; gap: .4em; margin-top: .5cqw; }\n.inv-dot { width: 7px; height: 7px; width: 5.2cqw; height: 5.2cqw; max-width: 8px; max-height: 8px; border-radius: 50%; background: var(--offline-color); }\n.inv-status-text { font-size: 11px; font-size: 7.8cqw; font-weight: 650; letter-spacing: .13em; color: var(--text-2); }\n\n.node-inverter[data-state=\"online\"] .inv-dot { background: var(--ok-color); box-shadow: 0 0 8px color-mix(in srgb, var(--ok-color) 60%, transparent); }\n.node-inverter[data-state=\"online\"] .inv-status-text { color: var(--ok-color); }\n.node-inverter[data-state=\"fault\"] { --tone: var(--danger-color); }\n.node-inverter[data-state=\"fault\"] .inv-dot { background: var(--danger-color); }\n.node-inverter[data-state=\"fault\"] .inv-status-text { color: var(--danger-color); }\n.node-inverter[data-state=\"standby\"] { --tone: var(--warn-color); }\n.node-inverter[data-state=\"standby\"] .inv-dot,\n.node-inverter[data-state=\"standby\"] .inv-status-text { color: var(--warn-color); background-color: var(--warn-color); }\n.node-inverter[data-state=\"standby\"] .inv-status-text { background: none; }\n.node-inverter[data-state=\"offline\"], .node-inverter[data-state=\"stale\"], .node-inverter[data-state=\"unknown\"] { --tone: var(--offline-color); }\n.node-inverter[data-state=\"offline\"] .inv-ring,\n.node-inverter[data-state=\"stale\"] .inv-ring,\n.node-inverter[data-state=\"unknown\"] .inv-ring { animation: none; opacity: .35; }\n\n/* ─── link labels ─── */\n\n.flow-label {\n  position: absolute;\n  transform: translate(-50%, -50%);\n  display: flex; align-items: center; gap: 5px;\n  padding: 3.5px 9px;\n  border-radius: 99px;\n  border: 1px solid var(--border);\n  background: rgba(10, 16, 24, .72);\n  backdrop-filter: blur(8px);\n  -webkit-backdrop-filter: blur(8px);\n  font-size: 11.5px; font-weight: 600;\n  white-space: nowrap;\n  pointer-events: auto;\n  transition: opacity .4s ease, color .3s;\n  color: var(--text-0);\n}\n.flow-label[data-align=\"left\"] { transform: translate(14%, -50%); }\n.flow-label[data-align=\"right\"] { transform: translate(-114%, -50%); }\n.flow-label[data-align=\"top\"] { transform: translate(-50%, -168%); }\n.flow-label[data-align=\"center\"] { transform: translate(-50%, -50%); }\n.flow-label.is-idle { opacity: .42; }\n.fl-arrow { font-size: 11px; line-height: 1; }\n.fl-solar { color: var(--solar-color); } .fl-battery { color: var(--battery-color); }\n.fl-grid { color: var(--grid-color); } .fl-load { color: var(--load-color); }\n.fl-generator { color: var(--generator-color); }\n.fl-value { color: var(--text-0); font-weight: 550; }\n\n/* ─── diagram footer: load coverage ─── */\n\n.flow-footer { margin-top: 14px; padding-top: 13px; border-top: 1px solid var(--border); }\n.flow-footer-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 9px; }\n\n.mix-bar {\n  display: flex; gap: 2px; height: 8px;\n  border-radius: 99px; overflow: hidden;\n  background: rgba(255, 255, 255, .05);\n}\n.mix-seg { display: block; width: var(--w, 0%); transition: width .6s cubic-bezier(.22, .61, .36, 1); border-radius: 99px; }\n.mix-seg.is-zero { display: none; }\n.mix-seg.mix-pv { background: linear-gradient(90deg, #ffcd6b, var(--solar-color)); }\n.mix-seg.mix-gen { background: linear-gradient(90deg, #ffa98f, var(--generator-color)); }\n.mix-seg.mix-batt { background: linear-gradient(90deg, #6ff0b4, var(--battery-color)); }\n.mix-seg.mix-grid { background: linear-gradient(90deg, #8dc0ff, var(--grid-color)); }\n.mix-bar.is-empty { opacity: .35; }\n\n.mix-legend { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 9px; font-size: 11.5px; color: var(--text-1); }\n.mix-item { display: flex; align-items: center; gap: 6px; }\n.mix-item i { width: 7px; height: 7px; border-radius: 2px; display: block; }\n.mix-item.mix-pv i { background: var(--solar-color); }\n.mix-item.mix-gen i { background: var(--generator-color); }\n.mix-item.mix-batt i { background: var(--battery-color); }\n.mix-item.mix-grid i { background: var(--grid-color); }\n.mix-item.is-muted { color: var(--text-2); }\n\n.alloc-list { display: flex; flex-wrap: wrap; gap: 7px; margin-top: 11px; }\n.alloc-chip {\n  display: flex; align-items: center; gap: 7px;\n  padding: 4px 9px;\n  border-radius: 8px;\n  border: 1px solid color-mix(in srgb, var(--tone, var(--border)) 22%, var(--border));\n  background: color-mix(in srgb, var(--tone, transparent) 7%, transparent);\n  font-size: 11.5px;\n}\n.alloc-label { color: var(--text-1); }\n.alloc-value { color: var(--text-0); font-weight: 600; }\n.alloc-chip.is-muted { color: var(--text-2); border-style: dashed; }\n\n/* ═══════════════════════════ BATTERY ═══════════════════════════ */\n\n.batt-main { display: flex; align-items: center; gap: 20px; margin-bottom: 16px; flex: 0 1 auto; }\n.batt-visual { flex: none; width: clamp(54px, 5.6vw, 90px); }\n.batt-svg { width: 100%; height: auto; display: block; }\n\n.card-battery { --batt-tone: var(--battery-color); }\n.card-battery[data-band=\"mid\"] { --batt-tone: #ffd166; }\n.card-battery[data-band=\"low\"] { --batt-tone: var(--warn-color); }\n.card-battery[data-band=\"critical\"] { --batt-tone: var(--danger-color); }\n.card-battery[data-band=\"unknown\"] { --batt-tone: var(--offline-color); }\n\n.batt-shell { fill: rgba(255, 255, 255, .022); stroke: var(--border-strong); stroke-width: 2; }\n.batt-cap { fill: var(--border-strong); }\n.batt-fill { fill: var(--batt-tone); opacity: .9; }\n.batt-fill-wrap { transition: transform .7s cubic-bezier(.22, .61, .36, 1); }\n.batt-ticks line { stroke: rgba(255, 255, 255, .18); stroke-width: 1.6; }\n.batt-stripes { opacity: 0; }\n.card-battery[data-mode=\"charge\"] .batt-stripes { opacity: 1; animation: stripes-up 1.6s linear infinite; }\n@keyframes stripes-up { to { transform: translateY(-26px); } }\n\n.batt-readout { min-width: 0; }\n.batt-power { display: flex; align-items: baseline; gap: 5px; margin-top: 4px; }\n.batt-power-num { font-size: 19px; font-weight: 450; color: var(--batt-tone); }\n.batt-power-unit { font-size: 12px; color: var(--text-1); }\n.batt-mode { display: block; margin-top: 3px; font-size: 10px; font-weight: 650; letter-spacing: .14em; color: var(--text-2); }\n.card-battery[data-mode=\"charge\"] .batt-mode { color: var(--battery-color); }\n.card-battery[data-mode=\"discharge\"] .batt-mode { color: var(--warn-color); }\n\n/* ═══════════════════════════ KPI ═══════════════════════════ */\n\n.kpi {\n  position: relative;\n  padding: 13px 15px 14px;\n  border-radius: var(--radius-sm);\n  border: 1px solid var(--border);\n  background: linear-gradient(165deg, rgba(255, 255, 255, .045), rgba(255, 255, 255, .012));\n  box-shadow: var(--inner-light), 0 14px 30px -24px rgba(0, 0, 0, .9);\n  overflow: hidden;\n}\n.kpi[hidden] { display: none; }\n.kpi::before {\n  content: ''; position: absolute; left: 0; top: 14%; bottom: 14%;\n  width: 2px; border-radius: 0 2px 2px 0;\n  background: var(--tone);\n  opacity: .8;\n}\n.kpi-head { display: flex; align-items: center; gap: 7px; margin-bottom: 9px; }\n.kpi-icon { color: var(--tone); display: grid; place-items: center; opacity: .85; }\n.kpi-label { font-size: 9.5px; font-weight: 650; letter-spacing: .13em; color: var(--text-2); text-transform: uppercase; }\n.kpi-value { display: flex; align-items: baseline; gap: 5px; }\n.kpi-num { font-size: clamp(21px, 1.9vw, 28px); font-weight: 300; letter-spacing: -.02em; line-height: 1; }\n.kpi-unit { font-size: 12px; font-weight: 500; color: var(--text-1); }\n\n/* ═══════════════════════════ CHARTS ═══════════════════════════ */\n\n.chart-host { position: relative; }\n.chart { position: relative; }\n.chart-canvas { position: relative; width: 100%; min-height: 120px; }\n.chart-svg { display: block; width: 100%; }\n\n.grid-line { stroke: rgba(255, 255, 255, .045); stroke-width: 1; }\n.grid-vertical { stroke: rgba(255, 255, 255, .028); }\n.grid-zero { stroke: rgba(255, 255, 255, .16); stroke-width: 1; }\n.axis-unit { fill: var(--text-2); font-size: 9.5px; letter-spacing: .08em; }\n.axis-label { fill: var(--text-2); font-size: 10px; font-family: var(--font); font-variant-numeric: tabular-nums; }\n.chart-line { stroke-linecap: round; stroke-linejoin: round; }\n.chart-crosshair { stroke: rgba(255, 255, 255, .28); stroke-width: 1; stroke-dasharray: 3 3; }\n.chart-bar { transition: fill-opacity .2s; }\n.chart-bar:hover { fill-opacity: 1; }\n\n.chart-legend { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 12px; }\n.chart-legend-item {\n  display: flex; align-items: center; gap: 7px;\n  padding: 5px 10px;\n  border-radius: 8px;\n  border: 1px solid var(--border);\n  background: var(--surface);\n  color: var(--text-1);\n  font: inherit; font-size: 11.5px;\n  cursor: pointer;\n  transition: opacity .15s, background .15s, border-color .15s;\n}\n.chart-legend-item:hover { background: var(--surface-2); border-color: var(--border-strong); }\n.chart-legend-item.is-off { opacity: .38; }\n.chart-legend-dot { width: 8px; height: 8px; border-radius: 2.5px; flex: none; }\n.chart-legend-value { color: var(--text-0); font-weight: 600; }\n\n.chart-tooltip {\n  position: absolute; left: 0; top: 0;\n  min-width: 132px; max-width: 100%;\n  padding: 9px 11px;\n  border-radius: 11px;\n  border: 1px solid var(--border-strong);\n  background: rgba(9, 14, 22, .93);\n  backdrop-filter: blur(12px);\n  -webkit-backdrop-filter: blur(12px);\n  box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 1);\n  font-size: 11.5px;\n  opacity: 0; pointer-events: none;\n  transition: opacity .12s;\n  z-index: 5;\n}\n.chart-tooltip.is-visible { opacity: 1; }\n.tt-title { font-size: 10.5px; letter-spacing: .1em; color: var(--text-2); margin-bottom: 6px; text-transform: uppercase; }\n.tt-row { display: flex; align-items: center; gap: 7px; padding: 2px 0; }\n.tt-dot { width: 7px; height: 7px; border-radius: 2px; flex: none; }\n.tt-label { color: var(--text-1); flex: 1 1 auto; }\n.tt-value { color: var(--text-0); font-weight: 600; white-space: nowrap; }\n.tt-value i { color: var(--text-2); font-style: normal; font-weight: 500; }\n\n.chart-empty {\n  position: absolute; inset: 0;\n  display: none; place-content: center; justify-items: center;\n  gap: 4px; padding: 0 16px; text-align: center;\n  color: var(--text-2); font-size: 12.5px;\n}\n.chart-empty.is-visible { display: grid; }\n.chart-empty-text { color: var(--text-1); }\n.chart-empty-hint { color: var(--text-2); font-size: 11.5px; max-width: 42ch; line-height: 1.45; }\n\n/* ═══════════════════════ period selector ═══════════════════════ */\n\n.date-nav { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }\n.nav-period { display: flex; align-items: center; gap: 4px; }\n.nav-btn { width: 28px; height: 28px; }\n.nav-btn[disabled] { opacity: .3; cursor: default; pointer-events: none; }\n\n.nav-label {\n  position: relative;\n  display: flex; align-items: center; gap: 7px;\n  padding: 5px 10px;\n  min-width: 132px;\n  justify-content: center;\n  border-radius: 9px;\n  border: 1px solid var(--border);\n  background: var(--surface);\n  color: var(--text-0);\n  font: inherit; font-size: 12px; font-weight: 600;\n  cursor: pointer;\n  white-space: nowrap;\n}\n.nav-label:hover { background: var(--surface-2); border-color: var(--border-strong); }\n.nav-label[hidden] { display: none; }\n.nav-cal { display: grid; place-items: center; color: var(--text-2); }\n/* The native picker drives the calendar; the visible chip shows the period\n   label, because \"August 2026\" reads better than \"01/08/2026\". */\n.nav-date-input {\n  position: absolute; inset: 0;\n  opacity: 0; width: 100%; padding: 0; border: none; pointer-events: none;\n}\n/* The month and year grids: a picker the platform does not provide, so it has\n   to look and behave the same everywhere. */\n.nav-pop {\n  position: absolute; top: calc(100% + 6px); left: 0; z-index: 40;\n  min-width: 208px; padding: 8px;\n  border-radius: 12px;\n  border: 1px solid var(--border-strong);\n  /* An opaque ground: the surface tokens are translucent overlays, and a\n     dropdown that shows the diagram through it is unreadable. */\n  background: var(--bg-2);\n  background-image: linear-gradient(180deg, var(--surface), transparent);\n  box-shadow: 0 18px 40px -18px rgba(0, 0, 0, .95);\n  cursor: default;\n}\n.nav-pop[hidden] { display: none; }\n.pop-head { display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-bottom: 6px; }\n.pop-title { font-size: 12px; font-weight: 700; letter-spacing: .06em; color: var(--text-0); }\n.pop-grid { display: grid; gap: 4px; }\n.pop-months { grid-template-columns: repeat(3, 1fr); }\n.pop-years { grid-template-columns: repeat(2, 1fr); }\n.pop-cell {\n  padding: 6px 8px;\n  border-radius: 8px;\n  border: 1px solid transparent;\n  background: transparent;\n  color: var(--text-1);\n  font: inherit; font-size: 11.5px; font-weight: 600;\n  cursor: pointer;\n}\n.pop-cell:hover:not([disabled]) { background: var(--surface); border-color: var(--border-strong); color: var(--text-0); }\n.pop-cell.is-active { background: rgba(255, 176, 32, .16); border-color: var(--solar-color); color: var(--text-0); }\n.pop-cell[disabled] { opacity: .32; cursor: default; }\n\n.nav-now { padding: 5px 11px; font-size: 11.5px; }\n.nav-now[hidden] { display: none; }\n\n.nav-custom { display: flex; align-items: center; gap: 6px; }\n.nav-custom[hidden] { display: none; }\n.nav-range-input { width: 132px; font-size: 12px; padding: 5px 8px; }\n.nav-dash { color: var(--text-2); }\n\n.range-switch {\n  display: flex; gap: 2px; padding: 2px;\n  border-radius: 10px;\n  border: 1px solid var(--border);\n  background: rgba(0, 0, 0, .22);\n}\n.range-btn {\n  padding: 5px 11px;\n  border: none; border-radius: 8px;\n  background: transparent;\n  color: var(--text-2);\n  font: inherit; font-size: 11.5px; font-weight: 600;\n  cursor: pointer;\n  transition: color .15s, background .15s;\n  white-space: nowrap;\n}\n.range-btn:hover { color: var(--text-0); }\n.range-btn.is-active { background: var(--surface-2); color: var(--text-0); box-shadow: var(--inner-light); }\n\n/* ═══════════════════════ PV strings / phases ═══════════════════════ */\n\n.string-list, .phase-list { display: flex; flex-direction: column; gap: 11px; margin-top: 13px; }\n.string-list:empty { display: none; }\n.string-row, .phase-row { display: flex; flex-direction: column; gap: 5px; }\n.string-row[hidden], .phase-row[hidden] { display: none; }\n.string-head, .phase-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }\n.string-name, .phase-name { font-size: 11px; font-weight: 650; letter-spacing: .1em; color: var(--text-2); }\n.string-value, .phase-value { font-size: 14px; font-weight: 550; }\n.string-meta, .phase-meta { font-size: 10.5px; color: var(--text-2); }\n.card-solar .bar-fill { --tone: var(--solar-color); }\n.card-phases .bar-fill { --tone: var(--phase-color); }\n.card-generator .bar-fill { --tone: var(--generator-color); }\n\n/* ═══════════════════════ ONBOARDING ═══════════════════════ */\n\n.onboard {\n  position: fixed; inset: 0;\n  z-index: 60;\n  display: grid; place-items: center;\n  padding: 20px;\n  background: rgba(4, 7, 12, .78);\n  backdrop-filter: blur(10px);\n  -webkit-backdrop-filter: blur(10px);\n}\n.onboard[hidden] { display: none; }\n.onboard-panel {\n  width: min(520px, 100%);\n  padding: 26px;\n  border-radius: var(--radius);\n  border: 1px solid var(--border-strong);\n  background: linear-gradient(170deg, rgba(20, 30, 44, .96), rgba(10, 15, 22, .96));\n  box-shadow: 0 40px 90px -40px rgba(0, 0, 0, 1);\n  text-align: center;\n}\n.onboard-icon {\n  width: 52px; height: 52px; margin: 0 auto 14px;\n  display: grid; place-items: center;\n  border-radius: 16px;\n  color: #1a1206;\n  background: linear-gradient(150deg, #ffd166, var(--solar-color));\n}\n.onboard-title { margin: 0 0 8px; font-size: 19px; font-weight: 600; }\n.onboard-body { color: var(--text-1); font-size: 13px; }\n.onboard-body p { margin: 0 0 14px; line-height: 1.55; }\n.onboard-actions { display: flex; flex-wrap: wrap; gap: 9px; justify-content: center; margin-top: 6px; }\n\n.btn {\n  padding: 9px 16px;\n  border-radius: 10px;\n  border: 1px solid var(--border-strong);\n  background: var(--surface-2);\n  color: var(--text-0);\n  font: inherit; font-size: 12.5px; font-weight: 600;\n  cursor: pointer;\n  transition: background .15s, border-color .15s, transform .1s;\n}\n.btn:hover { background: var(--surface-3); }\n.btn:active { transform: scale(.98); }\n.btn-primary {\n  border-color: transparent;\n  background: linear-gradient(160deg, #ffd166, var(--solar-color));\n  color: #1a1206;\n}\n.btn-primary:hover { filter: brightness(1.07); }\n.btn-ghost { background: transparent; }\n\n/* ═══════════════════════ SETTINGS (modal) ═══════════════════════ */\n\n.modal {\n  position: fixed; inset: 0;\n  z-index: 70;\n  display: flex; align-items: center; justify-content: center;\n  padding: 16px;\n  background: rgba(4, 7, 12, .74);\n  backdrop-filter: blur(8px);\n  -webkit-backdrop-filter: blur(8px);\n}\n.modal[hidden] { display: none; }\n.modal-panel {\n  display: flex; flex-direction: column;\n  width: min(880px, 100%);\n  max-height: min(88vh, 900px);\n  border-radius: var(--radius);\n  border: 1px solid var(--border-strong);\n  background: linear-gradient(172deg, rgba(18, 27, 40, .98), rgba(9, 14, 21, .98));\n  box-shadow: 0 50px 100px -40px rgba(0, 0, 0, 1);\n  overflow: hidden;\n}\n.modal-head {\n  display: flex; align-items: center; gap: 12px;\n  padding: 16px 18px;\n  border-bottom: 1px solid var(--border);\n}\n.modal-title { font-size: 15px; font-weight: 600; flex: 1 1 auto; }\n.modal-body { padding: 16px 18px; overflow: auto; flex: 1 1 auto; }\n.modal-foot {\n  display: flex; align-items: center; gap: 10px;\n  padding: 13px 18px;\n  border-top: 1px solid var(--border);\n  background: rgba(0, 0, 0, .16);\n}\n.modal-foot .spacer { flex: 1 1 auto; }\n.modal-status { font-size: 11.5px; color: var(--text-2); }\n.modal-status.is-ok { color: var(--ok-color); }\n.modal-status.is-warn { color: var(--warn-color); }\n\n.tabs { display: flex; gap: 2px; padding: 2px; border-radius: 10px; background: rgba(0, 0, 0, .25); border: 1px solid var(--border); }\n.tab-btn {\n  padding: 6px 13px; border: none; border-radius: 8px;\n  background: transparent; color: var(--text-2);\n  font: inherit; font-size: 12px; font-weight: 600; cursor: pointer;\n}\n.tab-btn.is-active { background: var(--surface-2); color: var(--text-0); }\n.tab-panel[hidden] { display: none; }\n\n.field-group { margin-bottom: 20px; }\n.field-group-head {\n  display: flex; align-items: center; gap: 8px; margin-bottom: 9px;\n  font-size: 10px; font-weight: 700; letter-spacing: .15em; text-transform: uppercase;\n  color: var(--tone, var(--text-2));\n}\n.field-group-head::after { content: ''; flex: 1 1 auto; height: 1px; background: var(--border); }\n\n.field {\n  display: grid;\n  grid-template-columns: minmax(140px, 1fr) minmax(0, 2fr);\n  align-items: center;\n  gap: 10px;\n  padding: 6px 0;\n}\n.field-label { font-size: 12.5px; color: var(--text-1); }\n.field-label small { display: block; font-size: 10.5px; color: var(--text-2); }\n.field-control { display: flex; align-items: center; gap: 8px; min-width: 0; }\n.field-control > input, .field-control > select { flex: 1 1 auto; min-width: 0; }\n.field-control > .icon-btn { width: 30px; height: 30px; }\n\nselect, input[type=\"text\"], input[type=\"number\"], input[type=\"password\"], input[type=\"url\"], textarea {\n  width: 100%; min-width: 0;\n  padding: 7px 9px;\n  border-radius: 9px;\n  border: 1px solid var(--border);\n  background: rgba(0, 0, 0, .3);\n  color: var(--text-0);\n  font: inherit; font-size: 12.5px;\n}\nselect { appearance: none; cursor: pointer; padding-right: 26px;\n  background-image: linear-gradient(45deg, transparent 50%, var(--text-2) 50%), linear-gradient(135deg, var(--text-2) 50%, transparent 50%);\n  background-position: right 12px center, right 7px center;\n  background-size: 5px 5px, 5px 5px;\n  background-repeat: no-repeat;\n}\nselect:hover, input:hover { border-color: var(--border-strong); }\noption { background: #101823; color: var(--text-0); }\ntextarea { min-height: 168px; resize: vertical; font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11.5px; }\n\n.conf-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--offline-color); }\n.conf-dot[data-c=\"high\"] { background: var(--ok-color); }\n.conf-dot[data-c=\"medium\"] { background: var(--warn-color); }\n.conf-dot[data-c=\"low\"] { background: var(--danger-color); }\n.conf-dot[data-c=\"manual\"] { background: var(--grid-color); }\n\n.field-state {\n  flex: 0 0 92px; text-align: right;\n  font-size: 10.5px; color: var(--text-2);\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n  font-variant-numeric: tabular-nums;\n}\n.conf-dot[data-c=\"mismatch\"] { background: var(--danger-color); opacity: .8; }\n\n.diag-table { width: 100%; border-collapse: collapse; font-size: 11.5px; }\n.diag-table th {\n  text-align: left; padding: 6px 8px;\n  font-size: 9.5px; letter-spacing: .11em; text-transform: uppercase; color: var(--text-2);\n  border-bottom: 1px solid var(--border);\n  position: sticky; top: 0; background: #0d141e;\n}\n.diag-table td { padding: 5px 8px; border-bottom: 1px solid rgba(255, 255, 255, .04); color: var(--text-1); vertical-align: top; }\n.diag-table td.mono { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 11px; color: var(--text-0); word-break: break-all; }\n.diag-table tr[data-status=\"unmapped\"] td { opacity: .45; }\n.diag-table tr[data-status=\"unavailable\"] td, .diag-table tr[data-status=\"missing\"] td { color: var(--danger-color); }\n.pill { display: inline-block; padding: 1px 6px; border-radius: 5px; border: 1px solid var(--border); font-size: 10px; }\n\n.switch { display: flex; align-items: center; gap: 9px; cursor: pointer; user-select: none; }\n.switch input { position: absolute; opacity: 0; width: 0; height: 0; }\n.switch-track {\n  width: 36px; height: 20px; border-radius: 99px; flex: none;\n  background: rgba(255, 255, 255, .1);\n  border: 1px solid var(--border);\n  position: relative;\n  transition: background .18s;\n}\n.switch-track::after {\n  content: ''; position: absolute; top: 2px; left: 2px;\n  width: 14px; height: 14px; border-radius: 50%;\n  background: var(--text-1);\n  transition: transform .18s, background .18s;\n}\n.switch input:checked + .switch-track { background: color-mix(in srgb, var(--accent-color) 55%, transparent); }\n.switch input:checked + .switch-track::after { transform: translateX(16px); background: #1a1206; }\n.switch-label { font-size: 12.5px; color: var(--text-1); }\n\n.help-text { font-size: 11.5px; color: var(--text-2); line-height: 1.6; }\n.help-text code {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: rgba(0, 0, 0, .35); padding: 1px 5px; border-radius: 5px; color: var(--accent-color);\n}\n.help-text a { color: var(--grid-color); }\n\n\n/* ═══════════════════════ sensor dialog ═══════════════════════ */\n\n.detail-panel { width: min(760px, 100%); }\n.detail-title { display: flex; flex-direction: column; gap: 2px; flex: 1 1 auto; min-width: 0; }\n.detail-entity {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: 11px; color: var(--text-2);\n  user-select: all; word-break: break-all;\n}\n.detail-nav {\n  padding: 11px 18px;\n  border-bottom: 1px solid var(--border);\n  background: rgba(0, 0, 0, .14);\n}\n.detail-chart { min-height: 300px; }\n.detail-chart[hidden] { display: none; }\n\n.detail-empty {\n  display: flex; flex-direction: column; align-items: center; justify-content: center;\n  gap: 8px; min-height: 240px; padding: 20px;\n  text-align: center; color: var(--text-1); font-size: 13px;\n}\n.detail-empty[hidden] { display: none; }\n.detail-empty small { color: var(--text-2); font-size: 11.5px; line-height: 1.6; max-width: 420px; }\n.detail-empty code {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  background: rgba(0, 0, 0, .35); padding: 1px 5px; border-radius: 5px; color: var(--accent-color);\n}\n\n.detail-stats { display: flex; gap: 18px; flex-wrap: wrap; }\n.detail-stat { display: flex; align-items: baseline; gap: 6px; }\n.detail-stat-label { font-size: 10px; letter-spacing: .12em; text-transform: uppercase; color: var(--text-2); }\n.detail-stat-value { font-size: 13.5px; font-weight: 600; }\n.detail-link { padding: 6px 12px; font-size: 11.5px; text-decoration: none; }\n\n/* responsive.css */\n/* responsive.css — layout across screen sizes.\n   Mobile order: flow -> KPI -> battery/grid/load -> charts. */\n\n/* ── wide desktop: a little more breathing room ── */\n@media (min-width: 1800px) {\n  :host { --gap: 18px; --pad: 22px; font-size: 15px; }\n  .flow-stage { max-height: 66vh; }\n}\n\n/* ── large screens: the diagram may take more height ── */\n@media (min-width: 1800px) and (min-height: 1000px) {\n  .flow-stage { --flow-max-h: 66vh; }\n}\n\n/* ── tablet: single column ── */\n@media (max-width: 1099px) {\n  :host { --gap: 12px; --pad: 16px; }\n  .card-flow { grid-column: 1 / -1; grid-row: auto; }\n  .card-battery, .card-grid { grid-column: 1 / -1; grid-row: auto; }\n  .kpi-row, .card-chart, .detail-row { grid-column: 1 / -1; grid-row: auto; }\n  .flow-stage { max-height: none; }\n  .batt-main { gap: 22px; }\n  .batt-visual { width: 76px; }\n}\n\n/* ── narrow tablet / large phone ── */\n@media (max-width: 780px) {\n  .kpi-row { grid-template-columns: repeat(auto-fit, minmax(132px, 1fr)); }\n  .detail-row { grid-template-columns: 1fr; }\n  .last-update { display: none; }\n}\n\n/* ── period selector on narrow screens ── */\n@media (max-width: 780px) {\n  .card-chart .card-head { flex-wrap: wrap; gap: 8px; }\n  .date-nav { width: 100%; justify-content: space-between; }\n  .nav-label { min-width: 108px; font-size: 11.5px; }\n  .nav-range-input { width: 116px; }\n  .history-bar { flex-wrap: wrap; }\n  .history-hint { display: none; }\n}\n\n/* ── phone ── */\n@media (max-width: 620px) {\n  :host { --gap: 10px; --pad: 14px; --radius: 17px; font-size: 13.5px; }\n  .app { padding: 8px 8px 22px; }\n\n  .topbar { padding: 7px 9px; gap: 8px; }\n  .brand-title-main { font-size: 13px; letter-spacing: .07em; }\n  /* On a phone the period selector earns its space by taking the brand's:\n     the logo mark still identifies the panel. */\n  .brand-text { display: none; }\n  .topbar-nav { flex: 1 1 auto; }\n  .topbar .nav-label { min-width: 0; flex: 1 1 auto; }\n  .topbar .date-nav { width: 100%; gap: 6px; }\n  .topbar .nav-range-select { flex: none; }\n  .status-chip { padding: 5px 9px; font-size: 10px; }\n  .status-chip .status-text { display: none; }\n  .status-chip .dot { width: 8px; height: 8px; }\n\n  /* mobile order: flow -> KPI -> battery/grid -> detail cards -> charts */\n  .card-flow { order: 1; }\n  .kpi-row { order: 2; grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .card-battery { order: 3; }\n  .card-grid { order: 4; }\n  .detail-row { order: 5; }\n  .nav-custom { width: 100%; }\n  .nav-range-input { flex: 1 1 0; width: auto; }\n  .card-chart { order: 6; }\n\n  .flow-label { font-size: 10.5px; padding: 2.5px 7px; gap: 4px; }\n  .flow-footer { margin-top: 10px; padding-top: 10px; }\n  .alloc-list { gap: 5px; }\n  .alloc-chip { font-size: 10.5px; padding: 3px 7px; }\n\n  .batt-main { gap: 14px; }\n  .batt-visual { width: 46px; }\n  .big-num { font-size: 32px; }\n\n  .chart-legend { gap: 5px; }\n  .chart-legend-item { padding: 4px 8px; font-size: 11px; }\n\n  .card-head { margin-bottom: 11px; }\n  .card-actions { gap: 7px; }\n  .range-btn { padding: 5px 9px; font-size: 11px; }\n\n  .field { grid-template-columns: 1fr; gap: 5px; }\n  .modal-panel { max-height: 94vh; }\n  .modal-body { padding: 13px; }\n}\n\n/* ── very narrow ── */\n@media (max-width: 400px) {\n  .kpi-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .range-switch { gap: 0; }\n  .range-btn { padding: 5px 7px; font-size: 10.5px; }\n}\n\n/* ── short viewport (phone in landscape) ── */\n@media (max-height: 560px) and (min-width: 700px) {\n  .flow-stage { max-height: 78vh; }\n}\n\n/* ── print: basic readability ── */\n@media print {\n  :host { background: #fff; color: #111; }\n  .card { border-color: #ddd; box-shadow: none; background: #fff; }\n  .topbar, .icon-btn, .range-switch { display: none; }\n}\n";
const DEMO_KEY = 'deye-dashboard:demo';
const CONN_KEY = 'deye-dashboard:connection';

class DeyeDashboardPanel extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._booted = false;
  }

  /* ── properties assigned by Home Assistant ── */

  set hass(hass) {
    this._hass = hass;
    if (this.app) this.app.setHass(hass);
  }
  get hass() { return this._hass; }

  set panel(panel) { this._panel = panel; }
  get panel() { return this._panel; }

  set narrow(v) { this._narrow = v; this.toggleAttribute('narrow', !!v); }
  get narrow() { return this._narrow; }

  set route(v) { this._route = v; }

  connectedCallback() {
    if (this._booted) return;
    this._booted = true;
    this._boot().catch((e) => this._fatal(e));
  }

  disconnectedCallback() {
    // Home Assistant may detach the panel while navigating — keep the state.
  }

  async _boot() {
    await this._injectStyles();

    setLanguage(resolveLanguage(null, null));   // browser locale for the pre-boot form
    const isStandalone = this.hasAttribute('standalone');
    const params = new URLSearchParams(location.search);
    const wantDemo = params.get('demo') === '1' || localStorage.getItem(DEMO_KEY) === '1';

    this._createApp();

    log(`Deye Dashboard v${VERSION} — mode: ${wantDemo ? 'demo' : isStandalone ? 'standalone' : 'panel'}`);

    if (wantDemo) {
      await this.app.init({ demo: true });
      return;
    }
    if (isStandalone) {
      const conn = readConnection();
      if (!conn) { this._askForToken(); return; }
      try {
        await this.app.init({ standalone: conn });
      } catch (e) {
        this._askForToken(String((e && e.message) || e));
      }
      return;
    }
    await this.app.init({ hass: this._hass || null });
  }

  /**
   * Builds a fresh dashboard instance. init() is not idempotent, so a retry
   * after a failed standalone login must replace the old instance instead of
   * appending a second one and leaking the first client's reconnect timer.
   */
  _createApp() {
    if (this.app) {
      try { this.app.destroy(); } catch (e) { /* already gone */ }
      this.shadowRoot.querySelectorAll('.deye-root, .modal, .onboard').forEach((n) => n.remove());
    }
    this.app = new DeyeDashboard(this.shadowRoot, {
      panelConfig: (this._panel && this._panel.config) || null,
      onToggleMenu: () => this._toggleHaMenu(),
      onDemoToggle: () => this._toggleDemo(),
    });
    return this.app;
  }

  async _injectStyles() {
    if (INLINE_CSS) {
      const style = document.createElement('style');
      style.textContent = INLINE_CSS;
      this.shadowRoot.append(style);
      return;
    }
    const links = CSS_FILES.map((file) => {
      const link = document.createElement('link');
      link.rel = 'stylesheet';
      link.href = new URL(`${file}?v=${VERSION}`, BASE).href;
      return link;
    });
    this.shadowRoot.append(...links);
    // Wait for the stylesheets so nothing flashes unstyled (but cap it at 1.5 s).
    await Promise.race([
      Promise.all(links.map((l) => new Promise((res) => { l.addEventListener('load', res, { once: true }); l.addEventListener('error', res, { once: true }); }))),
      new Promise((res) => setTimeout(res, 1500)),
    ]);
  }

  /** Menu button: on mobile HA hides the sidebar and this is the only way back. */
  _toggleHaMenu() {
    this.dispatchEvent(new CustomEvent('hass-toggle-menu', { bubbles: true, composed: true }));
  }

  _toggleDemo() {
    const on = localStorage.getItem(DEMO_KEY) === '1' || new URLSearchParams(location.search).get('demo') === '1';
    if (on) {
      // Leaving demo mode also has to drop ?demo=1, or the reload lands back in it.
      localStorage.removeItem(DEMO_KEY);
      const url = new URL(location.href);
      url.searchParams.delete('demo');
      location.replace(url.toString());
      return;
    }
    localStorage.setItem(DEMO_KEY, '1');
    location.reload();
  }

  /* ── standalone: connection form (index.html / debugging only) ── */

  _askForToken(errorText) {
    const wrap = document.createElement('div');
    wrap.className = 'onboard';
    wrap.innerHTML = `
      <div class="onboard-panel">
        <h2 class="onboard-title">${t('standalone.title')}</h2>
        <div class="onboard-body">
          <p>${t('standalone.text')}</p>
          ${errorText ? `<p style="color:var(--danger-color)">${errorText}</p>` : ''}
          <div class="field"><label class="field-label">${t('standalone.url')}</label><div class="field-control">
            <input id="d-url" type="url" value="${location.origin}" spellcheck="false"></div></div>
          <div class="field"><label class="field-label">${t('standalone.token')}</label><div class="field-control">
            <input id="d-token" type="password" placeholder="eyJhbGciOi..." spellcheck="false"></div></div>
          <div class="onboard-actions">
            <button class="btn btn-primary" id="d-connect" type="button">${t('standalone.connect')}</button>
            <button class="btn btn-ghost" id="d-demo" type="button">${t('standalone.demo')}</button>
          </div>
        </div>
      </div>`;
    this.shadowRoot.appendChild(wrap);
    const $ = (id) => wrap.querySelector(id);
    $('#d-connect').addEventListener('click', async () => {
      const url = $('#d-url').value.trim();
      const token = $('#d-token').value.trim();
      if (!url || !token) return;
      saveConnection({ url, token });
      wrap.remove();
      try {
        await this._createApp().init({ standalone: { url, token } });
      } catch (e) {
        clearConnection();
        this._askForToken(String((e && e.message) || e));
      }
    });
    $('#d-demo').addEventListener('click', () => { localStorage.setItem(DEMO_KEY, '1'); location.reload(); });
  }

  _fatal(err) {
    console.error('[DEYE] fatal start-up error:', err);
    const box = document.createElement('div');
    box.style.cssText = 'padding:24px;font:14px/1.5 system-ui;color:#ffb4b4';
    box.textContent = t('fatal', { msg: err && err.message ? err.message : err });
    this.shadowRoot.appendChild(box);
  }
}

function readConnection() {
  try {
    const raw = localStorage.getItem(CONN_KEY);
    const v = raw ? JSON.parse(raw) : null;
    return v && v.url && v.token ? v : null;
  } catch (e) { return null; }
}
function saveConnection(v) { try { localStorage.setItem(CONN_KEY, JSON.stringify(v)); } catch (e) {} }
function clearConnection() { try { localStorage.removeItem(CONN_KEY); } catch (e) {} }

if (!customElements.get('deye-dashboard')) {
  customElements.define('deye-dashboard', DeyeDashboardPanel);
}

export { DeyeDashboardPanel };
